using BloomGarden.Core.Model;
using UnityEngine;

namespace BloomGarden.Presentation
{
    /// <summary>
    /// Materials of the garden (GDD chapter 03 palette). Assets are generated by the editor menu
    /// "Bloom Garden/P3 - Construire la scene Game" so the URP shaders are referenced and kept in builds.
    /// </summary>
    [CreateAssetMenu(fileName = "GardenPalette", menuName = "Bloom Garden/Garden Palette")]
    public sealed class GardenPalette : ScriptableObject
    {
        [Header("Gameplay colors (coral, blue, yellow, purple)")]
        public Material[] flowers = new Material[ColorIds.Count];

        [Header("Garden")]
        public Material soil;
        public Material grass;
        public Material leaf;
        public Material slot;
        public Material lane;
        public Material marker;
        public Material dormant;
        public Material highlight;
        public Material flowerHeart;

        [Header("Diorama (P4)")]
        public Material water;
        public Material wood;
        public Material woodDark;
        public Material stone;
        public Material earth;
        public Material sand;
        public Material blossom;

        [Header("Themes (P7-02)")]
        public Material pondWater;
        public Material lily;
        public Material willow;
        public Material zenSand;
        public Material zenLine;
        public Material maple;
        public Material lantern;
        public Material bamboo;

        public Material Flower(ColorId color) => flowers[(int)color];
    }
}
